package simu.manufacturing;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static simu.manufacturing.Store.*;

@EnabledIfEnvironmentVariable(named="MANUFACTURING_TEST_DATABASE",matches=".+")
class MaterialPlanningTest {
 CustodyTest peer;
 @BeforeEach void setup(){peer=new CustodyTest();peer.setup();}
 @AfterEach void close(){if(peer!=null){peer.fixture.store.tx(c->{var r=current(c);sql(c,"UPDATE runs SET mode='standalone' WHERE id=?",r.get("id"));return null;});peer.close();}}
 Store store(){return peer.ingress;}
 void clock(double due){store().tx(c->{var r=current(c);sql(c,"UPDATE boundary_outbox SET sent_at=clock_timestamp() WHERE run_id=?",r.get("id"));sql(c,"UPDATE runs SET requested=GREATEST(requested,?) WHERE id=?",due,r.get("id"));return null;});store().grant(due,store().run().get("epoch"),null);}
 JsonNode release(UUID batch){var r=store().run();var body=Production.body(r,"release",number(r,"granted")+2);body.put("reference",batch.toString());var command=Production.command(store(),UUID.randomUUID().toString(),body,null);clock(body.path("due_at").asDouble());assertEquals("completed",store().execute(uuid(command.get("id"))));return store().tx(c->json(one(c,"SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.request.v1' AND envelope->>'causation_id'=?",r.get("id"),command.get("id").toString()).get("envelope")));}
 ObjectNode reserved(JsonNode request,ObjectNode... units){var e=(ObjectNode)request.deepCopy();UUID id=UUID.randomUUID();e.put("type","storage.reserve.completed.v1");e.put("event_id",UUID.randomUUID().toString());e.put("aggregate_id",id.toString());e.set("causation_id",request.get("event_id"));e.put("source","storage");e.put("destination","manufacturing");e.put("boundary","materials");e.put("wall_time","2026-10-25T00:00:00Z");e.put("effective_time",number(store().run(),"granted")+1);var p=e.putObject("payload");p.put("id",id.toString());p.set("run_id",request.get("run_id"));p.set("correlation_id",request.get("correlation_id"));p.set("sku",request.path("payload").get("sku"));p.set("quantity",request.path("payload").get("quantity"));p.put("location","RAW-A");p.put("purpose","production");p.put("status","reserved");p.put("version",1);p.set("unit_manifest",Json.M.valueToTree(units));return e;}
 UUID execute(ObjectNode event){return execute(event,"completed");}
 UUID execute(ObjectNode event,String result){assertEquals("accepted",store().ingest(event,"storage/events"));clock(event.path("effective_time").asDouble());UUID job=store().tx(c->uuid(one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",Policy.uuid(event.get("run_id")),"boundary:"+event.path("event_id").asText()).get("id")));assertEquals(result,store().execute(job));return job;}
 int sourceSlot;
 ObjectNode[] units(String sku,int count){var result=new ObjectNode[count];for(int i=0;i<count;i++){result[i]=(ObjectNode)peer.offer().path("unit");result[i].put("position","storage.raw.r01.b%02d.l%02d".formatted(1+sourceSlot/4,1+sourceSlot++%4));result[i].set("contents",Json.M.valueToTree(List.of(Map.of("sku",sku,"quantity",1))));}return result;}
 void deliver(UUID batch){var expected=store().tx(c->rows(c,"SELECT e.*,p.fact FROM production_material_expected e JOIN production_material_plans p ON p.id=e.reservation_id WHERE p.batch_id=? AND e.state='expected' ORDER BY e.unit_id",batch));for(var row:expected){var unit=(ObjectNode)json(row.get("offered_unit"));var h=peer.offer();h.set("unit",unit);h.set("origin",unit.get("position"));h.put("destination",row.get("destination").toString());var offer=peer.wire(h);offer.set("correlation_id",json(row.get("fact")).get("correlation_id"));execute(offer);var departed=h.deepCopy();departed.put("state","departed");var transit=unit.deepCopy();transit.put("state","in_transit");transit.putNull("position");transit.set("origin",h.get("origin"));transit.set("destination",h.get("destination"));transit.set("handoff_id",h.get("id"));for(var key:List.of("version","last_sequence","custody_generation"))transit.put(key,transit.path(key).asInt()+1);departed.set("unit",transit);departed.set("departure_token",Json.M.valueToTree(Map.of("id",UUID.randomUUID(),"handoff_id",Policy.uuid(h.get("id")),"unit_id",Policy.uuid(unit.get("id")),"run_id",store().run().get("id"),"epoch",store().run().get("epoch"),"custody_generation",transit.path("custody_generation").asInt(),"last_sequence",transit.path("last_sequence").asInt(),"unit_version",transit.path("version").asInt())));var receipt=peer.wire(departed);receipt.set("correlation_id",offer.get("correlation_id"));execute(receipt);}}
 List<JsonNode> requests(JsonNode first){return store().tx(c->rows(c,"SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.request.v1' AND envelope->>'causation_id'=? ORDER BY envelope->'payload'->>'sku'",Policy.uuid(first.get("run_id")),first.path("causation_id").asText()).stream().map(r->json(r.get("envelope"))).toList());}
 void twoMaterials(int other){var cfg=(ObjectNode)peer.fixture.get().path("config").deepCopy();((ObjectNode)cfg.path("products").get(0)).set("bom",Json.M.valueToTree(Map.of("COMPONENT",2,"OTHER",other)));peer.fixture.store.control("reset",1,store().run().get("id").toString(),null,Scenario.normalize(Json.M.valueToTree(Map.of("manufacturing",cfg))));peer.fixture.get();}
 void connected(){store().tx(c->{var r=current(c);sql(c,"UPDATE runs SET mode='helics' WHERE id=?",r.get("id"));return null;});}
 int issueCount(){return store().tx(c->rows(c,"SELECT id FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.issue.v1'",store().run().get("id")).size());}
 @Test void wholeRecipeAdmissionPreventsTwoBatchesFromBlockingEachOther(){
  twoMaterials(2);UUID a=peer.fixture.create(1),b=peer.fixture.create(1);connected();var ar=requests(release(a));var br=requests(release(b));
  var aa=reserved(ar.get(0),units("COMPONENT",2));var sibling=execute(aa,"waiting");assertEquals(0,issueCount(),"partial BOM cannot acquire cell slots");
  var ba=reserved(br.get(0),units("COMPONENT",2));execute(ba,"waiting");assertEquals(0,issueCount());
  var ab=reserved(ar.get(1),units("OTHER",2));execute(ab);assertEquals(2,issueCount());
  var bb=reserved(br.get(1),units("OTHER",2));var waiting=execute(bb,"waiting");assertEquals(2,issueCount());assertEquals(4,store().tx(c->rows(c,"SELECT unit_id FROM production_material_expected WHERE run_id=?",store().run().get("id"))).size());
  deliver(a);assertEquals("completed",store().execute(sibling));assertEquals("completed",store().tx(c->one(c,"SELECT status FROM production_commands WHERE id=?",sibling)).get("status"));assertEquals(2,issueCount());
  clock(number(store().run(),"granted")+1);var competing=store().tx(c->one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",store().run().get("id"),"production:start:"+b));assertEquals("waiting",store().execute(uuid(competing.get("id"))),"a queued batch cannot consume another batch's assigned recipe inputs");
  var start=store().tx(c->one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",store().run().get("id"),"production:start:"+a));assertEquals("completed",store().execute(uuid(start.get("id"))));assertEquals("running",peer.fixture.order(a).path("status").asText());
  clock(number(store().run(),"granted")+1);assertEquals("completed",store().execute(waiting));assertEquals(4,issueCount());assertEquals(4,store().tx(c->rows(c,"SELECT unit_id FROM production_material_expected WHERE run_id=? AND state='expected'",store().run().get("id"))).size());
 }
 @Test void impossibleWholeRecipeFootprintRejectsWithoutPromisingAnySlots(){
  twoMaterials(3);UUID batch=peer.fixture.create(1);connected();var requests=requests(release(batch));execute(reserved(requests.get(0),units("COMPONENT",2)),"waiting");var rejected=execute(reserved(requests.get(1),units("OTHER",3)));
  assertEquals("rejected",store().tx(c->one(c,"SELECT status FROM production_commands WHERE id=?",rejected)).get("status"));assertEquals(0,issueCount());assertEquals(0,store().tx(c->rows(c,"SELECT unit_id FROM production_material_expected WHERE run_id=?",store().run().get("id"))).size());
 }
 @Test void completeExistingRecipeIsReservedForItsBatchWithoutRequestingMoreStock(){
  var supply=peer.fixture.command(Map.of("action","supply","sku","COMPONENT","quantity",2));peer.fixture.advance(2);UUID batch=peer.fixture.create(1);connected();var body=Production.body(store().run(),"release",number(store().run(),"granted")+2);body.put("reference",batch.toString());var released=Production.command(store(),UUID.randomUUID().toString(),body,null);clock(body.path("due_at").asDouble());assertEquals("completed",store().execute(uuid(released.get("id"))));
  assertEquals(0,store().tx(c->rows(c,"SELECT id FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.request.v1'",store().run().get("id"))).size());var unit=store().tx(c->one(c,"SELECT * FROM production_handling_units WHERE command_id=?",Policy.uuid(supply.get("id"))));assertEquals("reserved",unit.get("state"));assertEquals(batch,unit.get("batch_id"));
  clock(number(store().run(),"granted")+1);var start=store().tx(c->one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",store().run().get("id"),"production:start:"+batch));assertEquals("completed",store().execute(uuid(start.get("id"))));assertEquals("running",peer.fixture.order(batch).path("status").asText());assertEquals(0,peer.fixture.get().path("materials").get(0).path("quantity").asInt());
 }
 @Test void partialExistingWholeUnitsReduceRequestsAndPreserveWholeRecipeAdmission(){
  var cfg=(ObjectNode)peer.fixture.get().path("config").deepCopy();((ObjectNode)cfg.path("products").get(0)).set("bom",Json.M.valueToTree(Map.of("COMPONENT",3,"OTHER",1)));peer.fixture.store.control("reset",1,store().run().get("id").toString(),null,Scenario.normalize(Json.M.valueToTree(Map.of("manufacturing",cfg))));peer.fixture.get();
  var supplied=peer.fixture.command(Map.of("action","supply","sku","COMPONENT","quantity",1));peer.fixture.advance(2);UUID batch=peer.fixture.create(1);connected();var requests=requests(release(batch));assertEquals(2,requests.get(0).path("payload").path("quantity").asInt(),"request only the missing quantity after reserving existing whole units");
  var local=store().tx(c->one(c,"SELECT * FROM production_handling_units WHERE command_id=?",Policy.uuid(supplied.get("id"))));assertEquals("reserved",local.get("state"));assertEquals(batch,local.get("batch_id"));
  execute(reserved(requests.get(0),units("COMPONENT",2)),"waiting");execute(reserved(requests.get(1),units("OTHER",1)));assertEquals(2,issueCount());assertEquals(3,store().tx(c->rows(c,"SELECT unit_id FROM production_material_expected WHERE run_id=?",store().run().get("id"))).size());
  deliver(batch);clock(number(store().run(),"granted")+1);var start=store().tx(c->one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",store().run().get("id"),"production:start:"+batch));assertEquals("completed",store().execute(uuid(start.get("id"))));assertEquals("running",peer.fixture.order(batch).path("status").asText());assertEquals(4,store().tx(c->rows(c,"SELECT unit_id FROM production_unit_inputs WHERE batch_id=?",batch)).size());
 }
 @Test void localWholeUnitSelectionCannotReuseTheCurrentCandidate(){
  var cfg=(ObjectNode)peer.fixture.get().path("config").deepCopy();((ObjectNode)cfg.path("products").get(0)).set("bom",Json.M.valueToTree(Map.of("COMPONENT",4)));peer.fixture.store.control("reset",1,store().run().get("id").toString(),null,Scenario.normalize(Json.M.valueToTree(Map.of("manufacturing",cfg))));peer.fixture.get();
  var manifest=List.of(Map.of("id","51000000-0000-4000-8000-000000000001","quantity",1),Map.of("id","52000000-0000-4000-8000-000000000001","quantity",1),Map.of("id","53000000-0000-4000-8000-000000000001","quantity",2));peer.fixture.command(Map.of("action","supply","sku","COMPONENT","quantity",4,"units",manifest));peer.fixture.advance(2);UUID batch=peer.fixture.create(1);connected();var body=Production.body(store().run(),"release",number(store().run(),"granted")+2);body.put("reference",batch.toString());var released=Production.command(store(),UUID.randomUUID().toString(),body,null);clock(body.path("due_at").asDouble());assertEquals("completed",store().execute(uuid(released.get("id"))));
  assertEquals(3,store().tx(c->rows(c,"SELECT id FROM production_handling_units WHERE batch_id=? AND state='reserved'",batch)).size());clock(number(store().run(),"granted")+1);var start=store().tx(c->one(c,"SELECT id FROM jobs WHERE run_id=? AND idempotency_key=?",store().run().get("id"),"production:start:"+batch));assertEquals("completed",store().execute(uuid(start.get("id"))));assertEquals(3,store().tx(c->rows(c,"SELECT unit_id FROM production_unit_inputs WHERE batch_id=?",batch)).size());
 }
 @Test void assignsSourceManifestsToTheirActualBatchCellsWithoutCreatingStock(){
  var cfg=(ObjectNode)peer.fixture.get().path("config").deepCopy();((ArrayNode)cfg.path("lines")).add(Json.M.valueToTree(Map.of("code","LINE-2","capacity",1,"products",List.of("PRODUCT"))));
  peer.fixture.store.control("reset",1,store().run().get("id").toString(),null,Scenario.normalize(Json.M.valueToTree(Map.of("manufacturing",cfg))));peer.fixture.get();UUID parent=UUID.randomUUID();
  var a=peer.fixture.command(Map.of("action","create","product","PRODUCT","line","LINE-1","quantity",1,"correlation_id",parent));var b=peer.fixture.command(Map.of("action","create","product","PRODUCT","line","LINE-2","quantity",1,"correlation_id",parent));peer.fixture.advance(2);
  store().tx(c->{var r=current(c);sql(c,"UPDATE runs SET mode='helics' WHERE id=?",r.get("id"));return null;});
  var requestA=release(Policy.uuid(a.get("id")));var requestB=release(Policy.uuid(b.get("id")));var unitA=(ObjectNode)peer.offer().path("unit");var unitB=(ObjectNode)peer.offer().path("unit");unitB.put("position","storage.raw.r01.b01.l02");
  var factA=reserved(requestA,unitA);execute(factA);var factB=reserved(requestB,unitB);execute(factB);
  assertEquals(0,peer.fixture.get().path("handling").path("units").size());assertEquals(0,peer.fixture.get().path("materials").get(0).path("quantity").asInt());
  var issues=store().tx(c->rows(c,"SELECT envelope FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.issue.v1'",store().run().get("id")));assertEquals(2,issues.size());
  for(var row:issues){var e=json(row.get("envelope"));var p=e.path("payload");boolean first=p.path("reference").equals(factA.path("aggregate_id"));var unit=first?unitA:unitB;assertEquals(first?"manufacturing.cell01.input01":"manufacturing.cell02.input01",p.path("unit_destinations").path(unit.path("id").asText()).asText());}
  assertEquals("duplicate",store().ingest(factA,"storage/events"));assertEquals(2,store().tx(c->rows(c,"SELECT id FROM boundary_outbox WHERE run_id=? AND envelope->>'type'='storage.issue.v1'",store().run().get("id"))).size());
  var local=peer.fixture.command(Map.of("action","supply","sku","COMPONENT","quantity",1));clock(number(store().run(),"granted")+2);assertEquals("completed",peer.fixture.store.execute(Policy.uuid(local.get("id"))));assertEquals("manufacturing.cell01.input02",peer.fixture.get().path("handling").path("units").get(0).path("position").asText());
  var h=peer.offer();h.set("unit",unitA);h.set("origin",unitA.get("position"));var e=peer.wire(h);e.put("correlation_id",parent.toString());
  var wrong=e.deepCopy();wrong.put("event_id",UUID.randomUUID().toString());((ObjectNode)wrong.path("payload")).put("destination","manufacturing.cell01.input03");var rejected=execute(wrong);assertEquals("rejected",store().tx(c->one(c,"SELECT status FROM production_commands WHERE id=?",rejected)).get("status"));
  execute(e);var departure=h.deepCopy();departure.put("state","departed");var transit=unitA.deepCopy();transit.put("state","in_transit");transit.putNull("position");transit.set("origin",h.get("origin"));transit.set("destination",h.get("destination"));transit.set("handoff_id",h.get("id"));transit.put("version",2);transit.put("last_sequence",2);transit.put("custody_generation",1);departure.set("unit",transit);departure.set("departure_token",Json.M.valueToTree(Map.of("id",UUID.randomUUID(),"handoff_id",Policy.uuid(h.get("id")),"unit_id",Policy.uuid(unitA.get("id")),"run_id",store().run().get("id"),"epoch",store().run().get("epoch"),"custody_generation",1,"last_sequence",2,"unit_version",2)));var delivered=peer.wire(departure);delivered.put("correlation_id",parent.toString());execute(delivered);
  assertEquals("received",store().tx(c->one(c,"SELECT status FROM production_material_plans WHERE id=?",Policy.uuid(factA.get("aggregate_id")))).get("status"));assertEquals(3,peer.fixture.get().path("materials").get(0).path("quantity").asInt());
 }
}
